SELECT
  c.retail_week_key,
  c.retail_year,
  c.retail_week,
  c.retail_week_label,
  c.store_key,
  c.store_id,
  c.store_name,
  c.region,
  c.store_format,
  c.net_revenue AS net_revenue_cy,
  p.net_revenue AS net_revenue_py,
  c.net_revenue - p.net_revenue AS net_revenue_change,
  c.sales_revenue AS sales_revenue_cy,
  p.sales_revenue AS sales_revenue_py,
  c.transactions AS transactions_cy,
  p.transactions AS transactions_py,
  c.units_sold AS units_sold_cy,
  p.units_sold AS units_sold_py,
  c.returns_value AS returns_value_cy,
  p.returns_value AS returns_value_py
FROM {{ ref('v_performance_store_week') }} AS c
JOIN {{ ref('dim_retail_week') }} AS w
  ON w.retail_week_key = c.retail_week_key
JOIN {{ ref('v_performance_store_week') }} AS p
  ON p.retail_week_key = w.prior_year_week_key AND p.store_key = c.store_key
WHERE
  c.is_comparable_week = 1
